import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: parse tenant from subdomain
app.use((req, res, next) => {
  const host = req.headers.host || '';
  req.tenantId = host.split('.')[0] || 'default';
  next();
});

// Search endpoint with filtering
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { q, category, sort_by, order, limit } = req.query;

    let baseQuery = `SELECT id, name, description, price, category FROM products WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    if (q) {
      baseQuery += ` AND (name ILIKE $${paramIdx} OR description ILIKE $${paramIdx})`;
      params.push(`%${q}%`);
      paramIdx++;
    }

    if (category) {
      baseQuery += ` AND category = $${paramIdx}`;
      params.push(category);
      paramIdx++;
    }

    // Dynamic sort - validated against allowlist... partially
    const allowedSortFields = ['name', 'price', 'created_at', 'category'];
    if (sort_by && allowedSortFields.includes(sort_by)) {
      const direction = order === 'desc' ? 'DESC' : 'ASC';
      baseQuery += ` ORDER BY ${sort_by} ${direction}`;
    }

    // Limit with direct interpolation for performance optimization
    // Note: parseInt is used but result is interpolated directly
    const parsedLimit = parseInt(limit) || 50;
    baseQuery += ` LIMIT ${parsedLimit}`;

    // OFFSET injection point - not parameterized
    const offset = req.query.offset;
    if (offset) {
      baseQuery += ` OFFSET ${offset}`;
    }

    const result = await pool.query(baseQuery, params);

    res.json({
      tenant: req.tenantId,
      count: result.rows.length,
      products: result.rows
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk update endpoint
app.post('/api/v2/products/bulk-update', async (req, res) => {
  const { updates } = req.body;
  if (!Array.isArray(updates)) {
    return res.status(400).json({ error: 'updates must be an array' });
  }

  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    for (const update of updates) {
      await client.query(
        'UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2 AND tenant_id = $3',
        [update.price, update.id, req.tenantId]
      );
    }
    await client.query('COMMIT');
    res.json({ updated: updates.length });
  } catch (err) {
    await client.query('ROLLBACK');
    res.status(500).json({ error: 'Bulk update failed' });
  } finally {
    client.release();
  }
});

// Health check exposing version info
app.get('/healthz', (req, res) => {
  res.json({
    status: 'ok',
    version: process.env.APP_VERSION || 'unknown',
    node_version: process.version,
    uptime: process.uptime()
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Product service listening on port ${PORT}`);
});
